// Formateá los datos del mes para el prompt
const data = $input.first().json;

const balance = data.balance ?? 0;
const income = data.totalIncome ?? 0;
const expenses = data.totalExpenses ?? 0;
const categories = (data.topCategories ?? []).slice(0, 5);

const today = new Date();
const weekStart = new Date(today);
weekStart.setDate(today.getDate() - 7);
const dateRange = `${weekStart.toLocaleDateString('es-AR')} al ${today.toLocaleDateString('es-AR')}`;

const catText = categories.map(c => `  • ${c.name}: $${c.amount.toLocaleString('es-AR')} (${c.percentage.toFixed(1)}%)`).join('\n');

const prompt = `Generá un resumen financiero semanal conciso para el usuario. Fecha: ${dateRange}.

DATOS DEL MES:
• Balance: $${balance.toLocaleString('es-AR')}
• Ingresos: $${income.toLocaleString('es-AR')}
• Gastos: $${expenses.toLocaleString('es-AR')}
• Top categorías:\n${catText || '  (sin datos)'}

El resumen debe tener:
1. Estado actual en una línea
2. 2-3 observaciones clave con números
3. 1 acción concreta para esta semana

Formato: texto plano, máximo 150 palabras, español rioplatense.`;

return [{ json: { prompt, balance, income, expenses, dateRange } }];
